// What you can catch where (NSW Illawarra coast), the bite model, and the recreational rules that apply.
// Data lives in species.js (generated by hand from the TideLine content dataset). Teacher note: size and bag limits follow
// DPIRD / worksheet values checked 31 Oct - 1 Nov 2026. They change from time to time — check
// https://www.dpi.nsw.gov.au/fishing/recreational/fishing-rules-and-regs before using the numbers in class.
import './fishLooks.js';
import { SPECIES, SPECIES_BY_ID, SPOT_INFO, STOCK_SEED } from './species.js';
import { SHY_SPECIES } from '../content/shop.js';

export { SPECIES, SPECIES_BY_ID, SPOT_INFO };

/** Rules by species id: min (cm, null = none), slotMax (cm, release above), bag, possession, protected, note. `minLength` kept as an alias. */
export const RULES = Object.fromEntries(SPECIES.map(s => [s.id, { ...s.rules, minLength: s.rules.min }]));

/** Catch tables by fishing spot: [species id, base weight, length range cm]. */
export const SPOTS = Object.fromEntries(Object.entries(SPOT_INFO).map(([k, info]) => [k, {
  label: info.label, blurb: info.blurb,
  fish: SPECIES.filter(s => s.spots[k]).map(s => [s.id, s.spots[k], s.length]),
}]));

/** How each species fights: profile for the catch bar (dart | shake | bolt | twitch | jet) and power 0..1. */
export const FIGHT = Object.fromEntries(SPECIES.map(s => [s.id, { profile: s.fight, power: s.power }]));

export const LURE_RIGS = new Set(['softplastic', 'metalslug', 'squidjig']);
export const TIDES = ['rising', 'high', 'falling', 'low'];
export const TIMES = ['dawn', 'day', 'dusk', 'night'];
export const SEASONS = ['summer', 'autumn', 'winter', 'spring'];

export const MISMATCH_RIG = 0.12; // rig match for a rig the species is not listed for
export const MISMATCH_BAIT = 0.2;
const COND_HIT = 1.4, COND_MISS = 0.7;

/** Default gear/conditions (used by tests and anything that calls pickCatch without a context). */
export const DEFAULT_CTX = { rig: 'runningsinker', bait: 'prawn', tide: null, time: null, season: null, stock: null, shy: 1, lureMod: 1, lit: 0 };

export const stockKey = (spot, id) => `${spot}:${id}`;
/** Stock health of a species at a spot (0-100): the saved value, else seeded from its NSW stock status. */
export function stockOf(stock, spot, id) {
  const v = typeof stock === 'function' ? stock(spot, id) : stock?.[stockKey(spot, id)];
  return v ?? STOCK_SEED[SPECIES_BY_ID[id]?.status ?? 'undefined'] ?? 60;
}

/** Nudge a stock-health value (kept in progress.stock, 0-100) up or down. */
export function adjustStock(progress, spot, id, delta) {
  progress.stock ??= {};
  progress.stock[stockKey(spot, id)] = Math.max(0, Math.min(100, Math.round(stockOf(progress.stock, spot, id) + delta)));
}

/** Does a species' hard gate let it bite? (Squid and cuttlefish: only on a squid jig, only at dusk and night.) An unknown time (tests) does not block. */
export function gateOpen(sp, ctx) {
  const g = sp.gate;
  if (!g) return true;
  if (g.rig && ctx.rig && !g.rig.includes(ctx.rig)) return false;
  if (g.time && ctx.time && !g.time.includes(ctx.time)) return false;
  return true;
}
/** The species that share a daily bag limit with this one (squid and cuttlefish: 20 together). */
export const bagGroupIds = id => { const g = SPECIES_BY_ID[id]?.rules.bagGroup; return g ? SPECIES.filter(s => s.rules.bagGroup === g).map(s => s.id) : [id]; };

const cond = (list, value) => (!list?.length || !value ? 1 : list.includes(value) ? COND_HIT : COND_MISS);
export const rigMatch = (sp, rig) => sp.rig[rig] ?? (rig === 'squidjig' ? 0.02 : MISMATCH_RIG); // a squid jig is hopeless for fish
export const baitMatch = (sp, rig, bait) => (LURE_RIGS.has(rig) ? 1 : !bait || bait === 'none' ? 0.1 : sp.bait[bait] ?? MISMATCH_BAIT);

/**
 * Every species at this spot with its bite weight: base × rig match × bait match × tide/time/season match × stock health / 100, then two small
 * gear modifiers (ctx from main.js biteContext): ctx.shy (your line: light line > 1 gives shy fish such as bream and luderick more bites, thick line < 1 fewer)
 * and ctx.lureMod (a lure's colour for today's water clarity and time of day, economy/effects.js; lure rigs only).
 */
export function biteWeights(spot, ctx = DEFAULT_CTX) {
  const out = [];
  for (const sp of SPECIES) {
    const base = sp.spots[spot];
    if (!base) continue;
    const rigM = rigMatch(sp, ctx.rig), baitM = baitMatch(sp, ctx.rig, ctx.bait);
    const condM = cond(sp.tide, ctx.tide) * cond(sp.time, ctx.time) * cond(sp.season, ctx.season);
    const stock = stockOf(ctx.stock, spot, sp.id);
    const lampM = 1 + (sp.lamp ?? 0) * (ctx.lit ?? 0);   // baitfish, squid and the fish that hunt them gather in a wharf lamp's pool of light
    const gearM = (SHY_SPECIES.includes(sp.id) ? ctx.shy ?? 1 : 1) * (LURE_RIGS.has(ctx.rig) ? ctx.lureMod ?? 1 : 1);
    const open = gateOpen(sp, ctx);
    out.push({ sp, base, rigM, baitM, condM, stock, gearM, lampM, open, w: open ? base * rigM * baitM * condM * (stock / 100) * gearM * lampM : 0, ideal: !sp.gate?.time || !ctx.time || sp.gate.time.includes(ctx.time) ? base * condM * (stock / 100) * lampM : 0 });
  }
  return out;
}

/** How well your tackle suits what is biting: 0..1 (weighted by how common each species is). Poor tackle lengthens the wait. */
export function gearFit(spot, ctx = DEFAULT_CTX) {
  const ws = biteWeights(spot, ctx);
  const w = ws.reduce((s, x) => s + x.w, 0), ideal = ws.reduce((s, x) => s + x.ideal, 0);
  return ideal > 0 ? w / ideal : 0;
}

/** Seconds to wait for a bite: 3-9 s with a good fit (a bit quicker when it is great), up to ~2.6x longer with poor tackle. */
export function waitFor(spot, ctx = DEFAULT_CTX, rnd = Math.random) {
  const fit = gearFit(spot, ctx), scale = 2.6 - 1.7 * Math.min(1, fit / 0.7);
  return (3 + rnd() * 6) * scale;
}

/**
 * Pick what bites. Returns { id, length, gear } where gear (0..1) is how well the rig and bait suit that species
 * (drives the catch-bar zone size). Poorly matched gear skews the length draw toward small fish, and every species with a
 * legal minimum has a chance of being under it (bigger with poor gear), so the rules always matter.
 * Old call style pickCatch(spot, rnd) still works.
 */
export function pickCatch(spot, ctx = DEFAULT_CTX, rnd = Math.random) {
  if (typeof ctx === 'function') { rnd = ctx; ctx = DEFAULT_CTX; }
  ctx = { ...DEFAULT_CTX, ...ctx };
  const ws = biteWeights(spot, ctx), total = ws.reduce((s, x) => s + x.w, 0);
  let pick = ws[0];
  if (total > 0) { let r = rnd() * total; for (const x of ws) { if ((r -= x.w) <= 0) { pick = x; break; } } }
  const { sp } = pick, [lo, hi] = sp.length, gear = pick.rigM * pick.baitM, q = Math.sqrt(Math.min(1, gear));
  let length;
  const min = sp.rules.min, slot = sp.rules.slotMax;
  if (min && rnd() < 0.08 + 0.3 * (1 - q)) length = Math.round(lo + (min - 1 - lo) * rnd());                // undersize
  else if (slot && rnd() < 0.07 * q) length = Math.round(slot + 1 + (hi - slot - 1) * rnd());               // over the slot
  else length = Math.round(lo + (hi - lo) * Math.pow(rnd(), 1.3 + (1 - q) * 2.2));                          // skewed small when mismatched
  return { id: sp.id, length: Math.max(lo, Math.min(hi, length)), gear: Math.round(gear * 100) / 100 };
}

/**
 * Is this catch legal to keep? keptToday = how many of the species you have already kept today;
 * inPossession = how many you have in your possession now (fridge and freezer included), defaults to keptToday.
 * Returns { legal, kind, reason } where kind is ok | protected | oversize | undersize | bag | possession.
 */
export function judge(id, length, keptToday, inPossession = keptToday) {
  const r = RULES[id];
  if (!r) return { legal: true, kind: 'ok', reason: '' };
  if (r.protected) return { legal: false, kind: 'protected', reason: r.note };
  if (r.slotMax && length > r.slotMax) return { legal: false, kind: 'oversize', reason: `Over the slot: ${length} cm is longer than ${r.slotMax} cm. Big fish are the best breeders, so release it.` };
  if (r.min && length < r.min) return { legal: false, kind: 'undersize', reason: `Undersize: ${length} cm is under the ${r.min} cm legal length. Release it so it can grow and breed.` };
  if (keptToday >= r.bag) return { legal: false, kind: 'bag', reason: `Bag limit reached: you may keep only ${r.bag} per day.` };
  if (inPossession >= r.possession) return { legal: false, kind: 'possession', reason: `Possession limit reached: you may have only ${r.possession} at any time, fridge and freezer included.` };
  return { legal: true, kind: 'ok', reason: r.note };
}
